namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

@page "/category/{CategorySlug}"

@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@RecipeService.GetCategoryDisplayName(CategorySlug) - RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="categories">Browse</a></li>
        <li class="breadcrumb-item active">@RecipeService.GetCategoryDisplayName(CategorySlug)</li>
    </ol>
</nav>

<h1>@RecipeService.GetCategoryDisplayName(CategorySlug)</h1>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes in this category yet. <a href="submit">Be the first to submit one!</a></p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategorySlug { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategorySlug);
    }
}

@page "/recipe/{RecipeId:int}"

@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (CurrentRecipe is null)
{
    <PageTitle>Recipe Not Found - RecipeShare</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe. <a href="categories">Browse all categories</a>.</p>
}
else
{
    <PageTitle>@CurrentRecipe.Title - RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Browse</a></li>
            <li class="breadcrumb-item"><a href="category/@CurrentRecipe.Category">@RecipeService.GetCategoryDisplayName(CurrentRecipe.Category)</a></li>
            <li class="breadcrumb-item active">@CurrentRecipe.Title</li>
        </ol>
    </nav>

    <h1>@CurrentRecipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="CurrentRecipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header">
                    <h5 class="mb-0">Ingredients</h5>
                </div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in CurrentRecipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="mb-1">• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header">
                    <h5 class="mb-0">Instructions</h5>
                </div>
                <div class="card-body">
                    @foreach (var step in CurrentRecipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? CurrentRecipe { get; set; }

    protected override void OnParametersSet()
    {
        CurrentRecipe = RecipeService.GetById(RecipeId);
    }
}

@rendermode InteractiveServer

@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star stars">
            @(star <= SelectedRating ? "★" : "☆")
        </span>
    }
    @if (Submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

<style>
    .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star:hover {
        transform: scale(1.2);
    }
    .star.selected {
        color: #ffc107;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int rating)
    {
        SelectedRating = rating;
        RecipeService.RateRecipe(RecipeId, rating);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="recipe/@SubmittedRecipeId">View your recipe</a> or <a href="submit" @onclick="ResetForm" @onclick:preventDefault>submit another</a>.
    </div>
}
else
{
    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => NewRecipe.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="beverages">Beverages</option>
                <option value="baking">Baking</option>
                <option value="vegetarian">Vegetarian</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="NewRecipe.Ingredients" placeholder="One ingredient per line" />
            <ValidationMessage For="() => NewRecipe.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => NewRecipe.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedRecipeId { get; set; }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = NewRecipe.Title,
            Category = NewRecipe.Category,
            Ingredients = NewRecipe.Ingredients,
            Steps = NewRecipe.Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedRecipeId = recipe.Id;
        SubmitSuccess = true;
    }

    private void ResetForm()
    {
        NewRecipe = new();
        SubmitSuccess = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

