toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="recipe/@SubmittedRecipeId">View your recipe</a> or <a href="submit" @onclick="ResetForm" @onclick:preventDefault>submit another</a>.
    </div>
}
else
{
    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => NewRecipe.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="beverages">Beverages</option>
                <option value="baking">Baking</option>
                <option value="vegetarian">Vegetarian</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="NewRecipe.Ingredients" placeholder="One ingredient per line" />
            <ValidationMessage For="() => NewRecipe.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => NewRecipe.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedRecipeId { get; set; }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = NewRecipe.Title,
            Category = NewRecipe.Category,
            Ingredients = NewRecipe.Ingredients,
            Steps = NewRecipe.Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedRecipeId = recipe.Id;
        SubmitSuccess = true;
    }

    private void ResetForm()
    {
        NewRecipe = new();
        SubmitSuccess = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

